// Asset manifest (public/assets/manifest.json, generated by tools/assets/build_manifest.py): types and a
// validating parser that builds lookup indexes. Paths are relative to the site root.

export type TextureMap = 'albedo' | 'normal' | 'rough' | 'opacity' | string;

export interface MaterialEntry {
  id: string;
  title: string;
  atlas: boolean;
  maps: Record<TextureMap, string>;
  size: [number, number];
}

export interface AssetEntry {
  id: string;
  path: string;
  kind: 'texture' | 'audio' | string;
  bytes: number;
  /** Texture only. */
  map?: TextureMap;
  material?: string;
  width?: number;
  height?: number;
  atlas?: boolean;
  /** Audio only. */
  category?: string;
  seconds?: number;
  loop?: boolean;
}

export interface Manifest {
  root: string;
  materials: Map<string, MaterialEntry>;
  assets: Map<string, AssetEntry>;
  byPath: Map<string, AssetEntry>;
}

export const MANIFEST_PATH = 'assets/manifest.json';

/** Parse and validate; throws with a readable message if the shape is wrong (the loader catches it). */
export function parseManifest(json: unknown): { manifest: Manifest; warnings: string[] } {
  const warnings: string[] = [];
  if (!json || typeof json !== 'object') throw new Error('manifest: not an object');
  const raw = json as { root?: unknown; materials?: unknown; assets?: unknown };
  if (!raw.materials || typeof raw.materials !== 'object') throw new Error('manifest: missing "materials"');
  if (!Array.isArray(raw.assets)) throw new Error('manifest: "assets" must be an array');
  const manifest: Manifest = { root: typeof raw.root === 'string' ? raw.root : 'public/', materials: new Map(), assets: new Map(), byPath: new Map() };
  for (const [id, m] of Object.entries(raw.materials as Record<string, unknown>)) {
    const e = m as Partial<MaterialEntry>;
    if (!e || typeof e.maps !== 'object' || e.maps === null) { warnings.push(`manifest: material ${id} has no maps`); continue; }
    const maps: Record<string, string> = {};
    for (const [k, v] of Object.entries(e.maps)) if (typeof v === 'string') maps[k] = v;
    manifest.materials.set(id, {
      id, title: typeof e.title === 'string' ? e.title : id, atlas: !!e.atlas, maps,
      size: Array.isArray(e.size) && e.size.length === 2 ? [Number(e.size[0]), Number(e.size[1])] : [0, 0],
    });
  }
  for (const a of raw.assets as unknown[]) {
    const e = a as Partial<AssetEntry>;
    if (!e || typeof e.id !== 'string' || typeof e.path !== 'string' || typeof e.kind !== 'string') { warnings.push('manifest: asset entry without id/path/kind skipped'); continue; }
    if (manifest.assets.has(e.id)) warnings.push(`manifest: duplicate asset id ${e.id}`);
    const entry: AssetEntry = { ...(e as AssetEntry), bytes: typeof e.bytes === 'number' ? e.bytes : 0 };
    manifest.assets.set(e.id, entry);
    manifest.byPath.set(e.path, entry);
  }
  return { manifest, warnings };
}

/** Texture asset id for a material map, as the manifest names them. */
export function textureAssetId(materialId: string, map: TextureMap): string {
  return `tex/${materialId}/${map}`;
}
